import React, { useState, useEffect } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

// Rows arrive one page at a time from SQL. Status and search are applied there
// too - filtering here would only ever filter the page on screen.
const COLS = [
  { key: "Bill Id", label: "Bill Id" },
  { key: "Customer", label: "Customer" },
  { key: "Billing ID", label: "Billing ID" },
  { key: "Vendor", label: "Vendor" },
  { key: "Invoice Date", label: "Invoice Date" },
  { key: "Utility", label: "Utility" },
  { key: "Account", label: "Account" },
  { key: "Meter", label: "Meter" },
  { key: "Severity", label: "Severity" },
  { key: "Message", label: "Message", wrap: 520 },
  { key: "Resolved", label: "Resolved" },
  { key: "Raised", label: "Raised" }
];

function App() {
  const [model, setModel] = useState(appsmith.model || {});
  const [status, setStatus] = useState((appsmith.model || {}).status || "all");
  const [q, setQ] = useState((appsmith.model || {}).search || "");

  useEffect(() => {
    const update = () => setModel({ ...(appsmith.model || {}) });
    update();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(update);
    const id = setInterval(update, 400);
    return () => clearInterval(id);
  }, []);

  const fetched = (model && model.data) || [];
  const page = Number(model.page) || 1;
  const pageSize = Number(model.pageSize) || 50;
  // The query returns one extra row purely to answer "is there another page".
  const rows = fetched.slice(0, pageSize);
  const hasMore = fetched.length > pageSize;
  const code = model.code == null ? "" : String(model.code);
  const cat = model.category || "";
  const name = model.name || "";

  const fire = (ev) => { if (typeof appsmith.triggerEvent === "function") appsmith.triggerEvent(ev); };
  const close = () => fire("onClose");
  // triggerEvent takes no arguments, so the intent is staged on the model and the
  // handler reads it back off the widget.
  const goPage = (delta) => { appsmith.updateModel({ pageDelta: delta }); fire("onPage"); };
  const applyFilter = (nextStatus, nextSearch) => {
    appsmith.updateModel({ pendingStatus: nextStatus, pendingSearch: nextSearch });
    fire("onFilter");
  };

  const cell = (r, c) => {
    if (c.key === "Severity") {
      const t = r["Severity"] == null ? "" : String(r["Severity"]);
      return t ? React.createElement("span", { className: "badge b-sev" + (r.severity_code || 20) }, t) : "";
    }
    if (c.key === "Resolved") {
      return r["Resolved"]
        ? React.createElement("span", { className: "badge b-info" }, "Resolved")
        : React.createElement("span", { className: "badge b-error" }, "Open");
    }
    const v = r[c.key];
    return v == null || v === "" ? React.createElement("span", { className: "empty" }, "—") : String(v);
  };

  const head = React.createElement("div", { className: "hd" },
    React.createElement("div", { className: "t" },
      React.createElement("h2", null, code ? "Code " + code + (cat ? "  ·  " + cat : "") : "Bill errors"),
      React.createElement("div", { className: "s" }, name)),
    React.createElement("button", { className: "x", onClick: close, title: "Close" }, "×"));

  const bar = React.createElement("div", { className: "bar" },
    React.createElement("div", { className: "fld" },
      React.createElement("label", null, "Status"),
      React.createElement("select", {
        value: status,
        onChange: (e) => { setStatus(e.target.value); applyFilter(e.target.value, q); }
      },
        React.createElement("option", { value: "all" }, "All"),
        React.createElement("option", { value: "open" }, "Open"),
        React.createElement("option", { value: "resolved" }, "Resolved"))),
    React.createElement("div", { className: "fld" },
      React.createElement("label", null, "Search bill, customer, account, meter or message"),
      React.createElement("input", {
        value: q, placeholder: "Type and press Enter",
        onChange: (e) => setQ(e.target.value),
        onKeyDown: (e) => { if (e.key === "Enter") applyFilter(status, q); }
      })));

  if (model.isLoading)
    return React.createElement("div", { className: "wrap" }, head, bar,
      React.createElement("div", { className: "skel" }, "Loading affected bills..."));

  return React.createElement("div", { className: "wrap" }, head, bar,
    React.createElement("div", { className: "meta" },
      rows.length ? ("Showing " + rows.length + " on page " + page) : ""),
    React.createElement("div", { className: "scroll" },
      React.createElement("table", { className: "tbl" },
        React.createElement("thead", null,
          React.createElement("tr", null,
            COLS.map((c) => React.createElement("th", { className: "noSort", key: c.key }, c.label)))),
        React.createElement("tbody", null,
          rows.length === 0
            ? React.createElement("tr", null,
                React.createElement("td", { className: "empty", colSpan: COLS.length },
                  page > 1 ? "No more bills" : "No bills match"))
            : rows.map((r, i) => React.createElement("tr", { key: i },
                COLS.map((c) => React.createElement("td", { key: c.key },
                  c.wrap ? React.createElement("div", { style: { maxWidth: c.wrap + "px" } }, cell(r, c)) : cell(r, c)))))))),
    React.createElement("div", { className: "pager" },
      React.createElement("button", { className: "pbtn", disabled: page <= 1, onClick: () => goPage(-1) }, "‹"),
      React.createElement("span", { className: "pnum" }, page),
      React.createElement("button", { className: "pbtn", disabled: !hasMore, onClick: () => goPage(1) }, "›"),
      React.createElement("span", { className: "gotolbl" }, pageSize + " per page")));
}

ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

